// middleware authenticates once and decorates the request
app.use(async (req, res, next) => {
  const principal = await verify(req.headers.authorization);
  if (!principal) return res.status(401).end();
  req.user = principal;                     // travels with the request object
  next();
});

// guard:
const requireRole = (role) => (req, res, next) =>
  req.user?.roles.includes(role) ? next() : res.status(403).end();
